import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import {
  Badge,
  Card,
  Table,
  Container,
  Row,
  Col,
} from "react-bootstrap";






// ... (ส่วนการ Import คงเดิม)

function Dashboard() {
  const [tableData, setTableData] = useState([]);
  const [chartData, setChartData] = useState({ labels: [], series: [] });
  const [stats, setStats] = useState({
    busStops: 0,
    cameras: "Active",
    alerts: 0,
    users: 0
  });

  const fetchData = async () => {
    try {
      const statsRes = await fetch('http://localhost:3000/api/dashboard-stats');
      const statsJson = await statsRes.json();
      setStats({
        busStops: statsJson.capacity || 0,
        cameras: "Active",
        alerts: statsJson.errors || 0, // รับค่าจำนวน Alerts จริง
        users: statsJson.followers || 0  // รับค่าจำนวนคนรวมจริง
      });

      const tableRes = await fetch('http://localhost:3000/api/table-data');
      const tableJson = await tableRes.json();
      setTableData(tableJson);

      const chartRes = await fetch('http://localhost:3000/api/chart-data');
      const chartJson = await chartRes.json();
      setChartData(chartJson);
    } catch (err) {
      console.error("Fetch Error:", err);
    }
  };

  useEffect(() => {
    fetchData(); 
    const interval = setInterval(fetchData, 10000); // อัปเดตทุก 10 วินาที
    return () => clearInterval(interval);
  }, []);

  return (
    <Container fluid>
      {/* ส่วน Card สถิติ: ปรับการแสดงผลตัวเลข */}
      <Row>
        <Col lg="3" sm="6">
          <Card className="card-stats">
            <Card.Body>
              <Row>
                <Col xs="7">
                  <div className="numbers">
                    <p className="card-category">Bus Stops</p>
                    <Card.Title as="h4">{stats.busStops} Stops</Card.Title>
                  </div>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
        {/* ... (การ์ดอื่นๆ ใช้โครงสร้างเดียวกัน) */}
        <Col lg="3" sm="6">
          <Card className="card-stats">
            <Card.Body>
              <Row>
                <Col xs="7">
                  <div className="numbers">
                    <p className="card-category">Total People</p>
                    <Card.Title as="h4">+{stats.users} Pax</Card.Title>
                  </div>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* ส่วนตาราง: แสดงเวลาที่อ่านง่ายขึ้น */}
      {/* ... (ในส่วน <tbody>) */}
      <td>
        {item.timestamp 
          ? new Date(item.timestamp).toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', second: '2-digit' }) 
          : "ไม่มีข้อมูล"}
      </td>
      {/* ... */}
      <div className="stats">
        <i className="fas fa-history"></i> Real-time: Updated every 10 Seconds
      </div>
    </Container>
  );
}





